# Помимо вывода проверяем саму форму класса: решение должно использовать изучаемую тему.
for task, class_name, fields, method, args, result in [
    (TASKS[0], 'Scoreboard', [('home', 'int'), ('away', 'int')], 'leader', '', 'String'),
    (TASKS[1], 'Parcel', [('box', 'int'), ('contents', 'int')], 'cost', '', 'int'),
    (TASKS[2], 'Wagon', [('capacity', 'int'), ('occupied', 'int')], 'canSeat', ', int.class', 'boolean'),
    (TASKS[3], 'PiggyBank', [('balance', 'int'), ('goal', 'int')], 'reached', '', 'boolean'),
]:
    checks = f'Class<?> c = cls("{class_name}"); need(c != null, "Создай класс {class_name}");\ntry {{\n'
    for name, typ in fields:
        checks += f'Field f_{name} = c.getDeclaredField("{name}"); need(f_{name}.getType() == {typ}.class && !Modifier.isStatic(f_{name}.getModifiers()), "Поле {name} должно иметь тип {typ} и быть без static");\n'
    checks += f'Method m = c.getDeclaredMethod("{method}"{args}); need(m.getReturnType() == {result}.class && !Modifier.isStatic(m.getModifiers()), "Проверь тип и параметры метода {method}; он должен быть без static");\n'
    checks += f'}} catch (ReflectiveOperationException e) {{ need(false, "Добавь поля и метод класса {class_name} по условию"); }}'
    task.checks = checks
